import {EVIDENCE} from './arg-content.js?v=42';
export function translateLegacy(hash){const [kind,id='']=String(hash||'').slice(1).split('/');if(kind==='portal'&&id==='ledger')return {site:'pan',params:{folder:'audit'}};if(kind==='portal')return {site:'canteen',params:{view:id==='workorders'?'outage':id==='ledger'?'contract':id==='order'?'card':id||'home'}};if(kind==='video')return {site:'video',params:id?{bv:id}:{}};if(kind==='pan')return {site:'pan',params:{folder:id==='ledger'?'audit':id||'accounts'}};if(kind==='doc'&&['letter','score'].includes(id))return {site:'pan',params:{folder:id==='letter'?'yida':'jie'}};if(kind==='doc'&&id==='paper')return {site:'forum',params:{thread:'leave'}};if(kind==='doc'){const key={by:'reportBy',wuji:'reportWuji',unknown:'reportUnknown',notebook:'diary'}[id]||id;return {site:'forum',params:{view:'doc',id:key}};}if(kind==='post')return {site:'forum',params:{thread:id}};if(kind==='chat'||kind==='chats')return {site:'forum',params:{thread:id==='chen'?'printing':'source'}};if(kind==='search')return {site:'forum',params:{q:decodeURIComponent(id)}};if(kind==='archive'){const e=EVIDENCE[id];return e?{site:e.site,params:e.params}:null;}if(['vault','board','outcome'].includes(kind))return {site:'pan',params:{folder:kind==='vault'?'audit':'notice'}};if(['recover','staff-login','annex'].includes(kind))return {site:'pan',params:{folder:'clinic'}};if(kind==='casefile'){if(id==='pickup'||id==='receipt')return {site:'canteen',params:{view:'card'}};const key=Object.keys(EVIDENCE).find(k=>EVIDENCE[k].sourceDoc===id);return key?{site:EVIDENCE[key].site,params:EVIDENCE[key].params}:null;}if(kind==='accounts'||kind==='locker')return {site:'pan',params:{folder:id==='azhe'?'heshe':id||'accounts'}};if(kind==='compare')return {site:'forum',params:{view:'compare'}};if(kind==='chapter'||kind==='resolution')return {site:'forum',params:{thread:id==='7'?'source':id==='12'||kind==='resolution'?'chen':'reports'}};return null;}
